/**
 * OSM layers generated by `npm run fetch-osm` (see scripts/fetch-osm.ts).
 * Don't edit the JSON by hand; re-run the script instead.
 * Data © OpenStreetMap contributors, ODbL.
 */
import type { Feature, FeatureCollection, LineString, MultiPolygon, Polygon } from 'geojson'
import boundaryJson from './osm/boundary.json'
import buildingsJson from './osm/buildings.json'
import roadsJson from './osm/roads.json'
import waterJson from './osm/water.json'
import greenJson from './osm/green.json'
import sportJson from './osm/sport.json'
import metaJson from './osm/meta.json'

export interface OsmBaseProps {
  id: string
  /** True when the feature lies inside the campus boundary. */
  inside: boolean
  name?: string
  'name:en'?: string
}

export interface BuildingProps extends OsmBaseProps {
  building: string
  'building:levels'?: string
  height?: string
  min_height?: string
}

export interface RoadProps extends OsmBaseProps {
  class: 'main' | 'minor' | 'path'
  highway: string
  service?: string
  bridge?: string
}

export interface AreaProps extends OsmBaseProps {
  landuse?: string
  leisure?: string
  natural?: string
  waterway?: string
  sport?: string
}

type FC<G extends Polygon | MultiPolygon | LineString, P> = FeatureCollection<G, P>

export const campusBoundary = boundaryJson as unknown as Feature<Polygon>
export const buildings = buildingsJson as unknown as FC<Polygon | MultiPolygon, BuildingProps>
export const roads = roadsJson as unknown as FC<LineString, RoadProps>
export const water = waterJson as unknown as FeatureCollection<Polygon | MultiPolygon | LineString, AreaProps>
export const green = greenJson as unknown as FC<Polygon | MultiPolygon, AreaProps>
export const sport = sportJson as unknown as FC<Polygon | MultiPolygon, AreaProps>
export const osmMeta = metaJson
